def life_generations(grid: list[list[int]], gens: int) -> int:
    h: int = len(grid)
    w: int = len(grid[0])
    cells: list[list[int]] = []
    for y in range(h):
        row: list[int] = []
        for x in range(len(grid[y])):
            row.append(grid[y][x])
        cells.append(row)
    for g in range(gens):
        nxt: list[list[int]] = []
        for y in range(h):
            nrow: list[int] = []
            for x in range(w):
                total: int = 0
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        if dy != 0 or dx != 0:
                            total += cells[(y + dy) % h][(x + dx) % w]
                alive: int = 0
                if total == 3 or (cells[y][x] == 1 and total == 2):
                    alive = 1
                nrow.append(alive)
            nxt.append(nrow)
        cells = nxt
    count: int = 0
    for y in range(h):
        for x in range(len(cells[y])):
            count += cells[y][x]
    return count

def knn_vote(train: list[list[float]], labels: list[int], query: list[float], k: int) -> int:
    n: int = len(train)
    dists: list[float] = []
    for r in range(n):
        dists.append(sum((train[r][c] - query[c]) * (train[r][c] - query[c]) for c in range(len(query))))
    taken: list[bool] = []
    for r in range(n):
        taken.append(False)
    votes: dict[int, int] = {}
    order: list[int] = []
    for t in range(k):
        best: int = -1
        for r in range(n):
            if not taken[r]:
                if best == -1 or dists[r] < dists[best]:
                    best = r
        if best == -1:
            break
        taken[best] = True
        order.append(best)
        votes[labels[best]] = votes.get(labels[best], 0) + 1
    winner: int = -1
    top: int = 0
    for idx in order:
        c2: int = votes.get(labels[idx], 0)
        if c2 > top:
            top = c2
            winner = labels[idx]
    return winner

def knn_vote(train: list[list[float]], labels: list[int], query: list[float], k: int) -> int:
    n: int = len(train)
    dists: list[float] = []
    for r in range(n):
        row: list[float] = train[r]
        width: int = min(len(row), len(query))
        d: float = 0.0
        for c in range(width):
            diff: float = row[c] - query[c]
            d += diff * diff
        dists.append(d)
    kk: int = k
    if k < 0:
        kk = n + k
        if kk < 0:
            kk = 0
    elif k > n:
        kk = n
    taken: list[bool] = []
    for r in range(n):
        taken.append(False)
    votes: dict[int, int] = {}
    order: list[int] = []
    for t in range(kk):
        best: int = -1
        for r in range(n):
            if not taken[r]:
                if best == -1 or dists[r] < dists[best]:
                    best = r
        taken[best] = True
        order.append(best)
        votes[labels[best]] = votes.get(labels[best], 0) + 1
    if len(order) == 0:
        raise ValueError("max() arg is an empty sequence")
    winner: int = -1
    top: int = 0
    for idx in order:
        c2: int = votes.get(labels[idx], 0)
        if c2 > top:
            top = c2
            winner = labels[idx]
    return winner
